use serde::{Deserialize, Serialize};

#[derive(Debug)]
pub struct User {
    pub id: u64,
    pub name: String,
}

/// Body of a request that carries an auth token (e.g. `POST /protected`).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthRequest {
    pub token: String,
}

/// Token the demo service accepts.
pub const VALID_TOKEN: &str = "secret-token";

pub fn log_request(path: &str) {
    println!("request: {}", path);
}

/// Returns `true` if `token` is an accepted auth token.
pub fn check_auth(token: &str) -> bool {
    token == VALID_TOKEN
}

use crate::middleware::{check_auth, log_request};
use crate::models::{AuthRequest, User};

/// Path of the token-guarded endpoint.
pub const PROTECTED_PATH: &str = "/protected";

pub fn get_user(id: u64) -> User {
    User { id, name: "anon".into() }
}

/// `/protected` handler: succeeds only when the request carries a valid token.
pub fn protected(req: &AuthRequest) -> Result<String, &'static str> {
    log_request(PROTECTED_PATH);

    if !check_auth(&req.token) {
        return Err("unauthorized");
    }

    Ok("protected resource".to_string())
}
